<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\Category;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class CategoryStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\CategoryModel',
  1 => 'App\\Controllers\\CategoryController',
  2 => 'App\\Validation\\CategoryRules',
  3 => 'App\\Entities\\CategoryEntity',
  4 => 'App\\Services\\CategoryService',
  5 => 'App\\Controllers\\Api\\V1\\CategoryApiController',
  6 => 'App\\API\\Resources\\CategoryResource',
  7 => 'App\\Validation\\CategoryApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
